Measure git dirs and worktrees of the main VPS repos — timeout 1500 ssh -o BatchMode=yes orchestra-vps 'nice -n 19 ionice -c3 python3 - <<'"'"'EOF'"'"'
import subprocess, os, glob, time
def sh(args, cwd=None, t=120):
    try: return subprocess.run(args, cwd=cwd, capture_output=True, text=True, timeout=t).stdout.strip()
    except Exception as e: return f"ERR {type(e).__name__}"
def du(p, t=180):
    out = sh(["du", "-sb", p], t=t); return int(out.split()[0]) if out and out.split()[0].isdigit() else -1
G = 2**30
repos = ["/home/kesha/katya-work", "/home/kesha/orchestra", "/opt/kesha-bot"] + sorted(p[:-5] for p in glob.glob("/home/kesha/projects/*/.git"))
now = time.time()
for r in repos:
    g = os.path.join(r, sh(["git", "--no-optional-locks", "rev-parse", "--git-common-dir"], r) or ".git")
    gsz = du(g)
    co = dict(l.split(": ") for l in sh(["git", "count-objects", "-v"], r).splitlines() if ": " in l)
    wts = []; cur = {}
    for l in sh(["git", "worktree", "list", "--porcelain"], r).splitlines() + [""]:
        if not l: 
            if cur: wts.append(cur); cur = {}
            continue
        k, _, v = l.partition(" "); cur[k] = v or True
    print(f"\n== {r}: git dir {gsz/G:.2f} GB (pack {int(co.get(\"size-pack\",0))/2**20:.0f} MB, loose {int(co.get(\"size\",0))/2**20:.0f} MB, garbage {int(co.get(\"size-garbage\",0))/2**20:.0f} MB), worktrees {len(wts)-1}")
    for w in wts[1:]:
        p = w.get("worktree"); 
        if not os.path.isdir(p): print(f"   MISSING {p}"); continue
        last = sh(["git", "--no-optional-locks", "log", "-1", "--format=%ct", "HEAD"], p)
        age = (now - int(last)) / 86400 if last.isdigit() else -1
        dirty = len(sh(["git", "--no-optional-locks", "status", "--porcelain", "--untracked-files=no"], p, 60).splitlines())
        inmain = sh(["git", "branch", "-a", "--contains", "HEAD", "--format=%(refname:short)"], p, 60).split()
        merged = any(b in ("main", "master", "origin/main", "origin/master") for b in inmain)
        mtime_age = (now - max(os.stat(p).st_mtime, os.stat(os.path.join(p, ".git")).st_mtime)) / 86400
        print(f"   {du(p, 120)/G:6.2f} GB  commit {age:5.1f}d  dirty {dirty:3}  {'in-main' if merged else 'NOT-in-main'}  {w.get(\"branch\", \"detached\").replace(\"refs/heads/\", \"\")[:40]}  {p}")
EOF' 2>&1 | tail -120; true

Delete verified old rollouts and leave a restore note — timeout 600 ssh -o BatchMode=yes orchestra-vps 'df -B1 / | tail -1 | awk "{print \"free before\", \$4/2^30}"; nice -n 15 ionice -c3 python3 - <<'"'"'EOF'"'"'
import os, time
root = "/home/kesha/.codex/sessions"; now = time.time()
rel = [l for l in open("/tmp/ops-rollout-list.txt").read().split("\n") if l]
targets = {os.path.join(root, r) for r in rel}
busy = set()
for pid in os.listdir("/proc"):
    if pid.isdigit():
        try:
            for fd in os.listdir(f"/proc/{pid}/fd"):
                try:
                    t = os.readlink(f"/proc/{pid}/fd/{fd}")
                    if t in targets: busy.add(t)
                except OSError: pass
        except OSError: pass
removed = skipped = freed = 0
for p in sorted(targets):
    try: st = os.stat(p)
    except FileNotFoundError: continue
    if p in busy or now - st.st_mtime < 7*86400: skipped += 1; continue
    os.unlink(p); removed += 1; freed += st.st_blocks * 512
print("removed", removed, "skipped", skipped, "freed GB", round(freed/2**30, 2))
EOF
